package dev.metallicarts.test;
import dev.metallicarts.arts.*;
import dev.metallicarts.domain.*;
import dev.metallicarts.economy.*;
import dev.metallicarts.equipment.*;
import dev.metallicarts.hemalurgy.*;
import dev.metallicarts.registry.ModRegistries;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import java.util.*;
public final class ReleaseGameplayGameTest {
 @GameTest public void memorySharingRequiresOptInMovesOneRecordAndPreservesProvenance(GameTestHelper c){var a=AdvancedSystemsGameTest.player(c);var b=AdvancedSystemsGameTest.player(c);b.teleportTo(a.getX()+1,a.getY(),a.getZ());var entry=new MemoryEntry(UUID.randomUUID(),"rest","My actual refuge","minecraft:overworld",12,80,34,5);a.setAttached(ModRegistries.JOURNAL,new ArtsJournal(List.of(entry),List.of(entry),List.of()));boolean denied=false;try{MemorySharing.transfer(a,b,entry.id());}catch(IllegalArgumentException e){denied=true;}c.assertTrue(denied&&a.getAttachedOrCreate(ModRegistries.JOURNAL).memories().size()==1,"No unsolicited private transfer");b.setAttached(ModRegistries.MEMORY_SHARING,true);MemorySharing.transfer(a,b,entry.id());c.assertTrue(a.getAttachedOrCreate(ModRegistries.JOURNAL).memories().isEmpty()&&b.getAttachedOrCreate(ModRegistries.JOURNAL).memories().equals(List.of(entry)),"One original ID/time/coordinates moves atomically");c.succeed();}
 @GameTest public void godmetalBurnConsumesOneBeadAndCannotStackFreeWindows(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setShiftKeyDown(true);var beads=new ItemStack(EconomyContent.ITEMS.get("atium_bead"),2);p.setItemInHand(InteractionHand.MAIN_HAND,beads);var item=(GodmetalItem)beads.getItem();item.use(c.getLevel(),p,InteractionHand.MAIN_HAND);c.assertTrue(beads.getCount()==1&&GodmetalRuntime.active(p).orElseThrow()==GodmetalRuntime.Kind.ATIUM,"Separate prepaid god-metal burn");item.use(c.getLevel(),p,InteractionHand.MAIN_HAND);c.assertTrue(beads.getCount()==1,"Existing window refuses duplicate consumption");c.assertTrue(GodmetalRuntime.payOpening(p),"Predicted opening pays from remaining finite window");c.succeed();}
 @GameTest public void eraOneAtiumAlloyRequiresElectrumAccessAndHasDistinctIdentity(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());p.setShiftKeyDown(true);var bead=new ItemStack(EconomyContent.ITEMS.get("nalatium_bead"));p.setItemInHand(InteractionHand.MAIN_HAND,bead);((GodmetalItem)bead.getItem()).use(c.getLevel(),p,InteractionHand.MAIN_HAND);c.assertTrue(bead.getCount()==1&&GodmetalRuntime.active(p).isEmpty(),"Pure and alloy capabilities are not conflated");AdvancedSystemsGameTest.grant(p,Art.ALLOMANCY,Metal.ELECTRUM);((GodmetalItem)bead.getItem()).use(c.getLevel(),p,InteractionHand.MAIN_HAND);c.assertTrue(bead.isEmpty()&&GodmetalRuntime.active(p).orElseThrow()==GodmetalRuntime.Kind.NALATIUM,"Associated alloy access works");c.succeed();}
 @GameTest public void supportedAtiumAlloyTransactionsPreserveInputsOnFailure(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(EconomyContent.ITEMS.get("atium_bead")));p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.DIRT));boolean denied=false;try{GodmetalCrafting.alloy(p);}catch(IllegalArgumentException e){denied=true;}c.assertTrue(denied&&p.getMainHandItem().getCount()==1&&p.getOffhandItem().getCount()==1,"No unsupported alloy output or consumed input");p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.GOLD_INGOT));GodmetalCrafting.alloy(p);c.assertTrue(p.getMainHandItem().is(EconomyContent.ITEMS.get("malatium_bead"))&&p.getOffhandItem().isEmpty(),"One supported alloy made");c.succeed();}
 @GameTest public void researchCampBuildsFiniteLootAndNeverOverwritesAnExistingContainer(GameTestHelper c){var origin=new BlockPos(10080,80,10080);c.getLevel().getChunkAt(origin);for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++){c.getLevel().setBlock(origin.offset(x,-1,z),Blocks.STONE.defaultBlockState(),3);for(int y=0;y<4;y++)c.getLevel().setBlock(origin.offset(x,y,z),Blocks.AIR.defaultBlockState(),3);}c.getLevel().setBlock(origin,Blocks.CHEST.defaultBlockState(),3);c.assertFalse(ResearchCampFeature.build(c.getLevel(),origin,c.getLevel().getRandom()),"Existing container blocks generation before any mutation");c.getLevel().setBlock(origin,Blocks.AIR.defaultBlockState(),3);c.assertTrue(ResearchCampFeature.build(c.getLevel(),origin,c.getLevel().getRandom()),"Valid empty site generates");c.assertTrue(c.getLevel().getBlockState(origin).is(EconomyContent.TABLE)&&c.getLevel().getBlockState(origin.offset(1,0,1)).is(Blocks.CHEST),"Real workstation and finite loot container exist");c.succeed();}
 @GameTest public void actualKolossNpcHasFourCanonicalDependenciesAndLosesStrengthWithOne(GameTestHelper c){var mob=c.spawn(NpcConstructs.KOLOSS,new BlockPos(2,2,2));c.assertTrue(NpcConstructs.implants(mob).size()==4,"Distinct spawned construct owns four actual staples");NpcConstructs.tick(mob);c.assertTrue(!mob.collapsed()&&mob.getAttribute(Attributes.ATTACK_DAMAGE).getModifier(dev.metallicarts.MetallicArts.id("npc_construct_force")).amount()>0,"Valid anatomy supplies strength");var a=NpcConstructs.implants(mob).get(0);SpikeLedger.get(c.getLevel().getServer()).release(a.token(),new AssetLease(mob.getUUID(),0),c.getLevel().getGameTime());mob.setAttached(ModRegistries.SPIKES,mob.getAttachedOrCreate(ModRegistries.SPIKES).with(0,ItemStack.EMPTY));NpcConstructs.tick(mob);c.assertTrue(mob.collapsed()&&mob.getAttribute(Attributes.ATTACK_DAMAGE).getModifier(dev.metallicarts.MetallicArts.id("npc_construct_force")).amount()<0,"Missing dependency actually debilitates body");c.succeed();}
 @GameTest public void actualInquisitorLinchpinLossKillsAndDoesNotRegenerateSpikes(GameTestHelper c){var mob=c.spawn(NpcConstructs.INQUISITOR,new BlockPos(2,2,2));c.assertTrue(NpcConstructs.implants(mob).size()==11,"Eleven actual prepared implants");var pin=NpcConstructs.implants(mob).get(11);SpikeLedger.get(c.getLevel().getServer()).release(pin.token(),new AssetLease(mob.getUUID(),11),c.getLevel().getGameTime());mob.setAttached(ModRegistries.SPIKES,mob.getAttachedOrCreate(ModRegistries.SPIKES).with(11,ItemStack.EMPTY));NpcConstructs.tick(mob);c.assertTrue(!mob.isAlive()&&mob.getAttachedOrCreate(ModRegistries.SPIKES).items().stream().allMatch(ItemStack::isEmpty),"Linchpin loss kills once and releases surviving physical implants");NpcConstructs.provision(mob);c.assertTrue(mob.getAttachedOrCreate(ModRegistries.SPIKES).items().stream().allMatch(ItemStack::isEmpty),"Initialized marker prevents minting replacements");c.succeed();}
 @GameTest public void actualKandraUsesLinkedBlessingAndCollapsesWhenItIsLost(GameTestHelper c){var mob=c.spawn(NpcConstructs.KANDRA,new BlockPos(2,2,2));NpcConstructs.tick(mob);c.assertTrue(!mob.collapsed()&&NpcConstructs.implants(mob).size()==2,"Actual paired Blessing body");var spike=NpcConstructs.implants(mob).get(0);SpikeLedger.get(c.getLevel().getServer()).release(spike.token(),new AssetLease(mob.getUUID(),0),c.getLevel().getGameTime());mob.setAttached(ModRegistries.SPIKES,mob.getAttachedOrCreate(ModRegistries.SPIKES).with(0,ItemStack.EMPTY));NpcConstructs.tick(mob);c.assertTrue(mob.collapsed(),"Body dependency is revalidated");c.succeed();}
 @GameTest public void permanentlyDiscardedNpcAssetsAreDestroyedButReleasedLootSurvives(GameTestHelper c){var mob=c.spawn(NpcConstructs.KANDRA,new BlockPos(2,2,2));var ledger=SpikeLedger.get(c.getLevel().getServer());var held=NpcConstructs.implants(mob);var released=held.get(0);var free=ledger.release(released.token(),new AssetLease(mob.getUUID(),0),c.getLevel().getGameTime());mob.setAttached(ModRegistries.SPIKES,mob.getAttachedOrCreate(ModRegistries.SPIKES).with(0,ItemStack.EMPTY));var owned=held.get(1).token();mob.discard();c.assertTrue(ledger.find(owned.instance()).isEmpty()&&ledger.resolve(free.token()).lease().isEmpty(),"Discard removes only still-owned assets, never free loot");c.succeed();}
 @GameTest public void npcMetalmindDiscardInvalidatesChargeInsteadOfLeakingLease(GameTestHelper c){var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));mob.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());AdvancedSystemsGameTest.grant(mob,Art.FERUCHEMY,Metal.STEEL);NpcFeruchemy.tick(mob);var token=mob.getAttachedOrCreate(ModRegistries.CONTACT_EQUIPMENT).item(0).get(ModRegistries.METALMIND).token();mob.discard();c.assertTrue(dev.metallicarts.feruchemy.MetalmindLedger.get(c.getLevel().getServer()).find(token.instance()).isEmpty(),"Permanent despawn cannot leave unreachable active charge");c.succeed();}
 @GameTest public void factionTradeAndViolenceChangeOnlyTheRelevantStanding(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setAttached(ModRegistries.FACTIONS,FactionStanding.empty());var merchant=c.spawn(EntityType.VILLAGER,new BlockPos(2,2,2));merchant.setAttached(ModRegistries.RESEARCHER,true);Factions.trade(merchant,p);c.assertTrue(p.getAttachedOrCreate(ModRegistries.FACTIONS).get("terris")==2&&p.getAttachedOrCreate(ModRegistries.FACTIONS).get("empire")==0,"Real researcher trade affects Terris standing only");merchant.hurtServer(c.getLevel(),p.damageSources().playerAttack(p),1);c.assertTrue(p.getAttachedOrCreate(ModRegistries.FACTIONS).get("terris")==-3,"Actual injury has a reputation cost");c.succeed();}
 @GameTest(maxTicks=100) public void ownerlessHarmoniumWaterReactionConsumesMaterialWithoutAnonymousDamage(GameTestHelper c){var pos=c.absolutePos(new BlockPos(2,2,2));c.getLevel().setBlock(pos,Blocks.WATER.defaultBlockState(),3);var mob=c.spawn(EntityType.PIG,new BlockPos(2,2,2));mob.setNoAi(true);float health=mob.getHealth();var item=new net.minecraft.world.entity.item.ItemEntity(c.getLevel(),pos.getX()+.5,pos.getY()+.2,pos.getZ()+.5,new ItemStack(EconomyContent.ITEMS.get("harmonium_sample")));c.getLevel().addFreshEntity(item);c.runAfterDelay(20,()->{c.assertTrue(item.isRemoved()||item.getItem().isEmpty(),"Actual water sample consumed");c.assertTrue(mob.getHealth()==health&&c.getLevel().getBlockState(pos).is(Blocks.WATER),"No anonymous injury or terrain destruction");c.succeed();});}
}
